const body = $json.body ?? $json;

const projectId =
  body.projectId ??
  body.project_id ??
  body.id ??
  'default';

const country =
  String(body.country ?? body.market ?? 'PL').trim().toUpperCase() || 'PL';

const maxQueriesPerSeedRaw =
  body.maxQueriesPerSeed ??
  body.settings?.maxQueriesPerSeed ??
  6;

const maxQueriesPerSeed = Math.max(
  3,
  Math.min(8, Number(maxQueriesPerSeedRaw) || 6)
);

let sourceSeeds =
  body.seeds ??
  body.discoverySeeds ??
  body.searchPlan?.seeds ??
  body.plan?.seeds ??
  body.searchTerms ??
  body.terms ??
  [];

if (!Array.isArray(sourceSeeds)) {
  sourceSeeds = [sourceSeeds];
}

function extractText(seed) {
  if (typeof seed === 'string') return seed;
  if (!seed || typeof seed !== 'object') return '';
  return (
    seed.text ??
    seed.seed ??
    seed.value ??
    seed.query ??
    seed.name ??
    seed.label ??
    ''
  );
}

function extractId(seed, index) {
  if (seed && typeof seed === 'object') {
    return String(
      seed.seedId ??
      seed.seed_id ??
      seed.id ??
      `seed-${index + 1}`
    );
  }
  return `seed-${index + 1}`;
}

const seeds = sourceSeeds
  .map((seed, index) => ({
    seedId: extractId(seed, index),
    text: String(extractText(seed)).replace(/\s+/g, ' ').trim(),
    source: seed && typeof seed === 'object'
      ? (seed.source ?? seed.origin ?? null)
      : null
  }))
  .filter(seed => seed.text.length > 0);

if (!seeds.length) {
  throw new Error(
    'MR03 requires at least one seed. Send body.seeds as an array of strings or objects with text/seed/value/query/name.'
  );
}

return [{
  json: {
    projectId,
    country,
    maxQueriesPerSeed,
    plannerVersion: 'mr03-query-planner-v1',
    seeds
  }
}];

