const payload = $json.output ?? $json;

if (!payload || !Array.isArray(payload.seedPlans)) {
  throw new Error('MR03 output is missing seedPlans[].');
}

const allowedTypes = new Set([
  'CORE',
  'PROBLEM',
  'AUDIENCE',
  'FORMAT',
  'SYNONYM',
  'PRECISION'
]);

function cleanQuery(text) {
  return String(text ?? '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function countTerms(text) {
  return cleanQuery(text).split(' ').filter(Boolean).length;
}

const source = $('Normalize Input').first().json;
const maxQueries = source.maxQueriesPerSeed ?? 6;

const seedPlans = payload.seedPlans.map((seedPlan, seedIndex) => {
  const seen = new Set();

  let queries = Array.isArray(seedPlan.queries) ? seedPlan.queries : [];

  queries = queries
    .map(q => {
      const text = cleanQuery(q.text);
      const termCount = countTerms(text);
      const queryTypeRaw = String(q.queryType ?? 'CORE').toUpperCase();
      const queryType = allowedTypes.has(queryTypeRaw) ? queryTypeRaw : 'CORE';
      const priority = Math.max(1, Math.min(100, Number(q.priority) || 50));

      return {
        text,
        termCount,
        queryType,
        priority,
        rationale: String(q.rationale ?? '').trim()
      };
    })
    .filter(q => {
      if (q.termCount < 2 || q.termCount > 3) return false;
      if (!q.text || seen.has(q.text)) return false;
      seen.add(q.text);
      return true;
    })
    .sort((a, b) => b.priority - a.priority)
    .slice(0, maxQueries);

  const threeWord = queries.filter(q => q.termCount === 3);
  if (threeWord.length > 2) {
    const keepThree = new Set(threeWord.slice(0, 2).map(q => q.text));
    queries = queries.filter(q => q.termCount === 2 || keepThree.has(q.text));
  }

  return {
    seedId: String(seedPlan.seedId ?? source.seeds?.[seedIndex]?.seedId ?? `seed-${seedIndex + 1}`),
    seedText: String(seedPlan.seedText ?? source.seeds?.[seedIndex]?.text ?? '').trim(),
    concept: String(seedPlan.concept ?? '').trim(),
    audience: Array.isArray(seedPlan.audience) ? seedPlan.audience.map(String) : [],
    formatHints: Array.isArray(seedPlan.formatHints) ? seedPlan.formatHints.map(String) : [],
    queries
  };
});

return [{
  json: {
    ok: true,
    projectId: String(payload.projectId ?? source.projectId),
    country: String(payload.country ?? source.country ?? 'PL').toUpperCase(),
    plannerVersion: String(payload.plannerVersion ?? source.plannerVersion ?? 'mr03-query-planner-v1'),
    status: 'DRAFT',
    generatedAt: new Date().toISOString(),
    seedPlans
  }
}];
